const notice = $('Claim Pending Completion Notices').item.json;
const task = $json;

const labels = {
  goal_achieved: 'Цель достигнута',
  declined: 'Собеседник отказался',
  stop_requested: 'Собеседник попросил прекратить диалог',
  not_relevant: 'Вопрос / задача неактуальны',
  other: 'Другая причина'
};

const reason = String(notice.completion_reason || 'other');
const reasonLabel = labels[reason] || labels.other;

const personName =
  String(
    notice.person_name ||
    notice.telegram_username ||
    'Собеседник'
  ).trim();

const username = String(notice.telegram_username || '').trim();

const personLine =
  username && username !== personName
    ? `${personName} (${username})`
    : personName;

const taskName =
  String(task.Name_task || task.id || notice.airtable_task_id || '').trim();

const finalResult = String(notice.final_result || '').trim();
const summary = String(notice.summary || '').trim();

let message =
  `Диалог завершён\n\n` +
  `Задача: ${taskName}\n` +
  `Собеседник: ${personLine}\n` +
  `Причина: ${reasonLabel}\n\n` +
  `Результат:\n${finalResult}`;

if (summary && summary !== finalResult) {
  message += `\n\nКратко:\n${summary}`;
}

return {
  json: {
    dialog_id: notice.dialog_id,
    airtable_dialog_id: notice.airtable_dialog_id,
    airtable_task_id: notice.airtable_task_id,
    task_name: taskName,
    admin_chat_id: String(task.admin_telegram_chat_id ?? '').trim(),
    admin_username: String(task.admin_telegram_username ?? '').trim(),
    admin_message: message
  }
};

const d = $json;
const username = String(d.admin_username || '').trim();

if (!username) {
  throw new Error(
    `Не заполнены admin_telegram_chat_id и admin_telegram_username для задачи ${d.task_name || d.airtable_task_id}. ` +
    `Уведомление остаётся pending и будет повторено после исправления задачи.`
  );
}

return { json: d };

